</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <cstdio>
#include <cstring>
#include <cctype>
#include <algorithm>
using namespace std;
const int dir[4][2]={{-1,0},{1,0},{0,-1},{0,1}};
int S,T,tot=1,n,tt,inf,b[1000],q[1000000],edge[1000000][3],head[1000],s[20][20],dep[20][20],dis[20][20],pid[20][20],sgrid[20][20];
char grid[20][20],bgrid[20][20];
void link(int u,int v,int cap)
{
    edge[++tot][0]=v,edge[tot][1]=cap,edge[tot][2]=head[u],head[u]=tot;
    edge[++tot][0]=u,edge[tot][1]=0,edge[tot][2]=head[v],head[v]=tot;
}
void bfs(int sx,int sy,bool build)
{
    int l=1,r=1,idx=pid[sx][sy];
    q[1]=sx*1000+sy;
    memset(dis,63,sizeof(dis));
    inf=dis[0][0];
    dis[sx][sy]=0;
    while(l<=r)
    {
        int cx=q[l]/1000,cy=q[l++]%1000;
        if(build && sgrid[cx][cy]!=0 && dis[cx][cy]<=tt && dis[cx][cy]<=dep[cx][cy])
            link(idx,sgrid[cx][cy],inf);
        if(dis[cx][cy]>tt || dis[cx][cy]>=dep[cx][cy])
            continue;
        if(idx==3 && sgrid[cx][cy]==9)
            printf("%d\n",dis[cx][cy]);
        for(int k=0;k<4;k++)
        {
            int nx=cx+dir[k][0],ny=cy+dir[k][1];
            if(nx>0 && nx<=n && ny>0 && ny<=n && isdigit(grid[nx][ny]) && dis[nx][ny]==inf)
            {
                dis[nx][ny]=dis[cx][cy]+1;
                q[++r]=nx*1000+ny;
            }
        }
    }
}
int depth[1000];
bool bfs_level()
{
    memset(depth,0,sizeof(depth));
    int l=1,r=1;
    q[1]=S;
    depth[S]=1;
    while(l<=r)
    {
        int u=q[l++];
        for(int i=head[u];i;i=edge[i][2])
        {
            int v=edge[i][0];
            if(depth[v] || edge[i][1]==0)
                continue;
            depth[v]=depth[u]+1;
            q[++r]=v;
            if(v==T)
                return true;
        }
    }
    return false;
}
int dfs(int u,int f)
{
    if(u==T)
        return f;
    int used=0;
    for(int i=head[u];i && f-used;i=edge[i][2])
    {
        int v=edge[i][0];
        if(depth[v]!=depth[u]+1 || edge[i][1]==0)
            continue;
        int pushed=dfs(v,min(f-used,edge[i][1]));
        used+=pushed;
        edge[i][1]-=pushed;
        edge[i^1][1]+=pushed;
    }
    if(used==0)
        depth[u]=-1;
    return used;
}
int main()
{
    scanf("%d%d",&n,&tt);
    for(int i=1;i<=n;i++)
        scanf("%s",grid[i]+1);
    for(int i=1;i<=n;i++)
        scanf("%s",bgrid[i]+1);
    memset(dep,63,sizeof(dep));
    for(int i=1;i<=n;i++)
        for(int j=1;j<=n;j++)
            if(grid[i][j]=='Z')
                bfs(i,j,false);
    memcpy(dep,dis,sizeof(dis));
    int node_count=1;
    S=0;
    T=1;
    for(int i=1;i<=n;i++)
        for(int j=1;j<=n;j++)
        {
            if(grid[i][j]>'0' && grid[i][j]<='9')
            {
                pid[i][j]=++node_count;
                link(S,pid[i][j],grid[i][j]-'0');
            }
            if(bgrid[i][j]>'0' && bgrid[i][j]<='9')
            {
                sgrid[i][j]=++node_count;
                link(sgrid[i][j],T,bgrid[i][j]-'0');
            }
        }
    for(int i=1;i<=n;i++)
        for(int j=1;j<=n;j++)
            if(pid[i][j])
                bfs(i,j,true);
    int maxflow=0;
    while(bfs_level())
        maxflow+=dfs(S,inf);
    printf("%d\n",maxflow);
    return 0;
}
